namespace Sakura\Vendor\Aws\ClientSideMonitoring;

use Sakura\Vendor\Aws\CommandInterface;
use Sakura\Vendor\Aws\Exception\AwsException;
use Sakura\Vendor\Aws\ResultInterface;
use Sakura\Vendor\GuzzleHttp\Psr7\Request;
use Sakura\Vendor\Psr\Http\Message\RequestInterface;

/**
 * @internal
 */
interface MonitoringMiddlewareInterface
{

    /**
     * Data for event properties to be sent to the monitoring agent.
     *
     * @param RequestInterface $request
     * @return array
     */
    public static function getRequestData(RequestInterface $request);


    /**
     * Data for event properties to be sent to the monitoring agent.
     *
     * @param ResultInterface|AwsException|\Exception $klass
     * @return array
     */
    public static function getResponseData($klass);

    public function __invoke(CommandInterface $cmd, RequestInterface $request);
}